import math

def root(n):
    # The square root of a whole number n, in simplest exact form
    if n == 0:
        return "0"
    k = math.isqrt(n)
    while n % (k * k) != 0:
        k = k - 1
    if k * k == n:
        return f"{k}"
    if k == 1:
        return f"√{n}"
    return f"{k}√{n // (k * k)}"

k = int(input())
for i in range(k):
    kind = input()
    x = int(input())
    y = int(input())
    if kind == "hyp":
        print(f"c = {root(x * x + y * y)}")
    elif y >= x:
        print("no triangle")
    else:
        print(f"b = {root(x * x - y * y)}")

k = int(input())
for i in range(k):
    a = int(input())
    b = int(input())
    c = int(input())
    if a > b:
        a, b = b, a
    if b > c:
        b, c = c, b
    if a > b:
        a, b = b, a
    if a + b <= c:
        kind = "not a triangle"
    elif c * c == a * a + b * b:
        kind = "right"
    elif c * c < a * a + b * b:
        kind = "acute"
    else:
        kind = "obtuse"
    print(f"{a}, {b}, {c}: {kind}")

