from fractions import Fraction

def show(coef, r):
    # coef times the square root of r, written the way you'd write it by hand
    if r == 1:
        return f"{coef}"
    if coef == 1:
        return f"√{r}"
    if coef.denominator == 1:
        return f"{coef}√{r}"
    return f"({coef})√{r}"

def half_square(case, known, value):
    print(case)
    v = Fraction(value)
    if known == "leg":
        print(f"  both legs are {value}")
        print(f"  hypotenuse = leg × √2 = {show(v, 2)}")
    else:
        print(f"  leg = {value}/√2 = {value}√2/2 = {show(v / 2, 2)}")

def half_equilateral(case, known, value):
    print(case)
    v = Fraction(value)
    if known == "short":
        print(f"  long leg = s√3 = {show(v, 3)}, hypotenuse = 2s = {show(2 * v, 1)}")
    elif known == "hyp":
        print(f"  short leg = {value}/2 = {show(v / 2, 1)}, long leg = {show(v / 2, 3)}")
    else:
        print(f"  short leg = {value}/√3 = {value}√3/3 = {show(v / 3, 3)}")
        print(f"  hypotenuse = 2s = {show(2 * v / 3, 3)}")

half_square("45-45-90, leg 7", "leg", 7)
half_square("45-45-90, hypotenuse 10", "hyp", 10)
