k = int(input())
for i in range(k):
    kind = input()
    known = input()
    v = Fraction(int(input()))
    if kind == "45":
        if known == "leg":
            leg_c, leg_r = v, 1
            hyp_c, hyp_r = v, 2
        else:
            leg_c, leg_r = v / 2, 2
            hyp_c, hyp_r = v, 1
        print(f"leg {show(leg_c, leg_r)}, leg {show(leg_c, leg_r)}, hyp {show(hyp_c, hyp_r)}")
    else:
        if known == "short":
            s_c, s_r = v, 1
            l_c, l_r = v, 3
            h_c, h_r = 2 * v, 1
        elif known == "hyp":
            s_c, s_r = v / 2, 1
            l_c, l_r = v / 2, 3
            h_c, h_r = v, 1
        else:
            s_c, s_r = v / 3, 3
            l_c, l_r = v, 1
            h_c, h_r = 2 * v / 3, 3
        print(f"short {show(s_c, s_r)}, long {show(l_c, l_r)}, hyp {show(h_c, h_r)}")

