import math

def root(n):
    # The square root of a whole number n, in simplest exact form
    if n == 0:
        return "0"
    k = math.isqrt(n)
    while n % (k * k) != 0:
        k = k - 1
    if k * k == n:
        return f"{k}"
    if k == 1:
        return f"√{n}"
    return f"{k}√{n // (k * k)}"

def paren(n):
    # A negative number gets parentheses, as you'd write it by hand
    if n < 0:
        return f"({n})"
    return f"{n}"

def distance(case, p, q):
    print(case)
    total = 0
    for i in range(len(p)):
        diff = q[i] - p[i]
        print(f"  {q[i]} - {paren(p[i])} = {diff}, squared {diff * diff}")
        total = total + diff * diff
    if root(total) == f"√{total}":
        print(f"  d = √{total}, no square factor to take out")
    else:
        print(f"  d = √{total} = {root(total)}")

distance("The plain case", [1, 2], [4, 6])
distance("Negative coordinates", [-2, 5], [4, -3])
distance("An exact radical", [1, -1], [3, 5])
distance("A vertical segment", [3, -2], [3, 7])
distance("In space", [1, 2, 3], [3, 5, 9])
distance("In space, a radical", [1, 1, 1], [2, 3, 4])

